examples.template:
Row(verticalAlignment = Alignment.CenterVertically) {
    MonarchText(text = {{metric}}, style = MonarchTextStyle.Label)
    Box {
        MonarchIconButton(label = {{label}}, onClick = { open = true }) {
            MonarchIcon(SampleIcons.Info, contentDescription = null)
        }
        MonarchPopover(
            expanded = open,
            onDismissRequest = { open = false },
            label = {{label}},
            side = MonarchPopoverSide.Bottom,
        ) {
            MonarchText(text = {{message}})
        }
    }
}

